        "    u32 inst_size = 4;\n"
        "    u32 inst = cpu->memory.Read32(phys_addr & 0xFFFFFFFC);\n\n"
        "    // If we are in Thumb mode, we'll translate one Thumb instruction to the corresponding ARM\n"
        "    // instruction\n"
