        "        inst = arm_inst;\n"
        "    }\n\n"
        "    int idx;\n"
        "    if (DecodeARMInstruction(inst, &idx) == ARMDecodeStatus::FAILURE) {\n"
        "        LOG_ERROR(Core_ARM11, \"Decode failure.\\tPC: [{:#010X}]\\tInstruction: {:08X}\", phys_addr,\n"
        "                  inst);\n"
        "        LOG_ERROR(Core_ARM11, \"cpsr={:#X}, cpu->TFlag={}, r15={:#010X}\", cpu->Cpsr, cpu->TFlag,\n"
        "                  cpu->Reg[15]);\n"
