        "static int clz(unsigned int x) {\n"
        "    int n;\n"
        "    if (x == 0)\n"
        "        return (32);\n"
        "    n = 1;\n"
        "    if ((x >> 16) == 0) {\n"
        "        n = n + 16;\n"
        "        x = x << 16;\n"
        "    }\n"
        "    if ((x >> 24) == 0) {\n"
