        "        inst_cream->link_gen = cur_gen;\n"
        "        inst_cream->taken_ptr = target;\n"
        "        ptr = target;\n"
        "        inst_base = (arm_inst*)&trans_cache_buf[ptr];\n"
        "        GOTO_NEXT_INST;\n"
        "    }\n"
        "    goto DISPATCH;\n"
        "}\n"
        "B_COND_THUMB: {\n"
        "    b_cond_thumb* inst_cream = (b_cond_thumb*)inst_base->component;\n"
        "    const bool taken = CondPassed(cpu, inst_cream->cond);\n"
        "    if (taken)\n"
        "        cpu->Reg[15] = (cpu->Reg[15] + 4 + inst_cream->imm) & 0xfffffffeU;\n"
        "    else\n"
        "        cpu->Reg[15] = (cpu->Reg[15] + 2) & 0xfffffffeU;\n"
