        "    u32& link_slot = taken ? inst_cream->taken_ptr : inst_cream->fallthrough_ptr;\n"
        "    if (inst_cream->link_gen == cur_gen && link_slot != DynComICache::INVALID) {\n"
        "        ptr = link_slot;\n"
        "        inst_base = (arm_inst*)&trans_cache_buf[ptr];\n"
        "        GOTO_NEXT_INST;\n"
        "    }\n"
        "    const u32 target = cpu->instruction_cache.find(cpu->Reg[15] | 1u);\n"
        "    if (target != DynComICache::INVALID) {\n"
