        "            inst_cream->fallthrough_ptr = DynComICache::INVALID;\n"
        "            inst_cream->link_gen = cur_gen;\n"
        "        }\n"
        "        link_slot = target;\n"
        "        ptr = target;\n"
        "        inst_base = (arm_inst*)&trans_cache_buf[ptr];\n"
        "        GOTO_NEXT_INST;\n"
        "    }\n"
