    replace_once(
        dsp_simd_hpp,
        "\t// Mixes the stereo output of a DSP voice into a quadraphonic intermediate mix\n"
        "\tstatic void mix(IntermediateMix& mix, StereoFrame16& frame, const float* gains) {\n"
        "#if defined(DSP_SIMD_ARM64)\n"
        "\t\treturn mixNEON(mix, frame, gains);\n"
        "#elif defined(DSP_SIMD_X64) && (defined(__SSE4_1__) || defined(__AVX__))\n"
        "\t\treturn mixSSE4_1(mix, frame, gains);\n"
        "#else\n"
        "\t\treturn mixPortable(mix, frame, gains);\n"
        "#endif\n"
        "\t}",
        "#ifdef DSP_SIMD_WASM\n"
        "\tALWAYS_INLINE static void mixWasmSIMD(IntermediateMix& mix, StereoFrame16& frame, const float* gains) {\n"
        "\t\tv128_t gains_ = wasm_v128_load(gains);\n"
        "\t\tfor (usize sampleIndex = 0; sampleIndex < Audio::samplesInFrame; sampleIndex++) {\n"
        "\t\t\tv128_t stereoSamples = wasm_v32x4_load_splat(&frame[sampleIndex][0]);\n"
        "\t\t\tv128_t currentFrame = wasm_f32x4_convert_i32x4(wasm_i32x4_extend_low_i16x8(stereoSamples));\n"
        "\t\t\tv128_t offset = wasm_i32x4_trunc_sat_f32x4(wasm_f32x4_mul(currentFrame, gains_));\n"
        "\t\t\tv128_t prev = wasm_v128_load(&mix[sampleIndex][0]);\n"
        "\t\t\twasm_v128_store(&mix[sampleIndex][0], wasm_i32x4_add(prev, offset));\n"
        "\t\t}\n"
        "\t}\n"
        "#endif\n\n"
        "\t// Mixes the stereo output of a DSP voice into a quadraphonic intermediate mix\n"
        "\tstatic void mix(IntermediateMix& mix, StereoFrame16& frame, const float* gains) {\n"
        "#if defined(DSP_SIMD_ARM64)\n"
        "\t\treturn mixNEON(mix, frame, gains);\n"
        "#elif defined(DSP_SIMD_X64) && (defined(__SSE4_1__) || defined(__AVX__))\n"
        "\t\treturn mixSSE4_1(mix, frame, gains);\n"
        "#elif defined(DSP_SIMD_WASM)\n"
        "\t\treturn mixWasmSIMD(mix, frame, gains);\n"
        "#else\n"
        "\t\treturn mixPortable(mix, frame, gains);\n"
        "#endif\n"
        "\t}",
    )

